        },
        "required": ["keys"]
      },
      "UpdatePermissionDto": {
        "type": "object",
        "properties": {
          "permission": {
            "type": "string",
            "description": "Permission level for the share",
            "enum": ["read", "write"]
          },
          "encryptedIpnsKey": {
            "type": "string",
            "description": "Hex-encoded ECIES ciphertext of IPNS private key. Required when upgrading to write, omitted when downgrading to read."
          }
        },
        "required": ["permission"]
      },
      "UpdateEncryptedKeyDto": {
        "type": "object",
        "properties": {
          "encryptedKey": {
            "type": "string",
            "description": "Hex-encoded ECIES ciphertext of the new key wrapped for recipient"
          }
        },
        "required": ["encryptedKey"]
      },
      "InviteStatusResponseDto": {
        "type": "object",
        "properties": {
          "status": {
            "type": "string",
            "enum": ["active"],
            "description": "Invite status. Only \"active\" is returned; all other states result in 404 to prevent token-existence oracle attacks."
          }
        },
        "required": ["status"]
      },
      "InviteChildKeyDto": {
        "type": "object",
        "properties": {
          "keyType": {
            "type": "string",
            "description": "Type of key: file, folder, or file-ipns",
            "enum": ["file", "folder", "file-ipns"]
          },
          "itemId": {
            "type": "string",
            "description": "UUID of the file or subfolder"
          },
          "encryptedKey": {
            "type": "string",
            "description": "Hex-encoded ECIES ciphertext of the key wrapped with ephemeral public key"
          }
        },
        "required": ["keyType", "itemId", "encryptedKey"]
      },
      "InviteDataResponseDto": {
        "type": "object",
        "properties": {
          "status": {
            "type": "string",
            "enum": ["active", "expired", "claimed", "revoked"],
            "description": "Current status of the invite"
          },
          "encryptedKey": {
            "type": "string",
            "description": "Hex-encoded item key wrapped with ephemeral public key"
          },
          "encryptedChildKeys": {
            "description": "Array of child keys wrapped with ephemeral public key, or null",
            "nullable": true,
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/InviteChildKeyDto"
            }
          },
          "itemType": {
            "type": "string",
            "enum": ["folder", "file"]
          },
          "ipnsName": {
            "type": "string",
            "description": "IPNS name of the shared item"
          },
          "itemName": {
            "type": "string",
            "description": "Display name of the shared item"
          }
        },
        "required": [
          "status",
          "encryptedKey",
          "encryptedChildKeys",
          "itemType",
          "ipnsName",
          "itemName"
        ]
      },
      "ClaimChildKeyDto": {
        "type": "object",
        "properties": {
          "keyType": {
            "type": "string",
            "description": "Type of key: file, folder, or file-ipns",
            "enum": ["file", "folder", "file-ipns"]
          },
          "itemId": {
            "type": "string",
            "description": "UUID of the file or subfolder"
          },
          "encryptedKey": {
            "type": "string",
            "description": "Hex-encoded ECIES ciphertext of the key re-wrapped for recipient"
          }
        },
        "required": ["keyType", "itemId", "encryptedKey"]
      },
      "ClaimInviteDto": {
        "type": "object",
        "properties": {
          "encryptedKey": {
            "type": "string",
            "description": "Hex-encoded item key re-wrapped for the recipient via ECIES"
          },
          "childKeys": {
            "description": "Re-wrapped child keys for subfolders/files",
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/ClaimChildKeyDto"
            }
          }
        },
        "required": ["encryptedKey"]
      },
      "ClaimInviteResponseDto": {
        "type": "object",
        "properties": {
          "shareId": {
            "type": "string",
            "description": "UUID of the created share"
          }
        },
        "required": ["shareId"]
      },
      "CreateInviteDto": {
        "type": "object",
        "properties": {
          "itemType": {
            "type": "string",
            "description": "Type of shared item",
            "enum": ["folder", "file"]
          },
          "ipnsName": {
            "type": "string",
            "description": "IPNS name of the shared item"
          },
          "itemName": {
            "type": "string",
            "description": "Display name of the shared item"
          },
          "encryptedKey": {
            "type": "string",
            "description": "Hex-encoded item key wrapped with ephemeral public key via ECIES"
          },
          "encryptedChildKeys": {
            "description": "Re-wrapped descendant keys (subfolder/file keys) with ephemeral public key",
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/InviteChildKeyDto"
            }
          }
        },
        "required": ["itemType", "ipnsName", "itemName", "encryptedKey"]
      },
      "InviteResponseDto": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Invite UUID (for management operations like revoke)"
          },
          "token": {
            "type": "string",
            "description": "Invite token (URL-safe base64)"
          },
          "itemType": {
            "type": "string",
            "enum": ["folder", "file"]
          },
          "ipnsName": {
            "type": "string",
            "description": "IPNS name of the shared item"
          },
          "itemName": {
            "type": "string",
            "description": "Display name of the shared item"
          },
          "status": {
            "type": "string",
            "enum": ["active", "claimed", "revoked"]
          },
          "expiresAt": {
            "type": "string",
            "description": "When the invite expires",
            "format": "date-time"
          },
          "createdAt": {
            "type": "string",
            "description": "When the invite was created",
            "format": "date-time"
          }
        },
        "required": [
          "id",
          "token",
          "itemType",
          "ipnsName",
          "itemName",
          "status",
          "expiresAt",
          "createdAt"
        ]
      },
      "ConnectionTestRequestDto": {
        "type": "object",
        "properties": {
          "encryptedConfig": {
            "type": "string",
            "description": "ECIES-encrypted provider config (hex-encoded)"
          },
          "epoch": {
            "type": "number",
            "description": "TEE epoch for key selection"
          }
        },
        "required": ["encryptedConfig", "epoch"]
      },
      "ConnectionTestResponseDto": {
        "type": "object",
        "properties": {
          "success": {
            "type": "boolean",
            "description": "Whether the connection test succeeded"
          },
          "protocol": {
            "type": "string",
            "enum": ["kubo", "psa"],
            "description": "Detected protocol"
          },
          "version": {
            "type": "string",
            "description": "Provider version string"
          },
          "latencyMs": {
            "type": "number",
            "description": "Probe latency in milliseconds"
          },
          "error": {
            "type": "string",
            "description": "Error message on failure"
          }
        },
        "required": ["success", "latencyMs"]
      }
    }
  }
}

